/* Shared narrative screen and commerce panel; story hooks stay disabled until authored. */
window.WAVE_CONTENT=window.WAVE_CONTENT||{};window.WAVE_CONTENT.oak??={};window.WAVE_CONTENT.residents??={};
window.WAVE_CONTENT.oak[2]={"title": "Кого боится лес", "lines": [{"speaker": "Рассказчик", "text": "Влад останавливается у Дуба. После второй ночи руки ещё дрожат от усталости. Он смотрит на тёмный лес и только потом поднимает глаза к ветвям.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "Снова пришли. Со всех сторон, будто заранее знали, куда идти. Скажи мне: почему им нужна эта деревня? Что здесь такого, ради чего они будут возвращаться?", "bg": "oak-conversation.webp"}, {"speaker": "Дуб с цепями", "text": "Не деревня.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "Не деревня? А мы тогда что всю ночь защищали? Они шли к домам, к мостам… Я едва успевал их остановить.", "bg": "oak-conversation.webp"}, {"speaker": "Дуб с цепями", "text": "Дома стоят на пути. Им нужно то, что внутри.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "Тогда что? Не заставляй меня вытягивать из тебя каждое слово. Я устал, Дуб. Люди могут погибнуть, пока я гадаю.", "bg": "oak-conversation.webp"}, {"speaker": "Дуб с цепями", "text": "Маленький человек.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "Ребёнок?.. Они пришли за ребёнком?", "bg": "oak-conversation.webp", "oakFact": "child-target"}, {"speaker": "Рассказчик", "text": "Влад замолкает. На миг ему снова восемь лет: холодный погреб, щели между досками и чужой голос над головой — «Ищите мальчика».", "bg": "oak-conversation.webp"}, {"speaker": "Голос", "text": "Прекрасно. Значит, мы защищаем ребёнка от целого леса. А я-то надеялся, что у нас хотя бы на этот раз будет задача попроще.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "Наверняка всё очень просто. Осталось только понять, кто этот ребёнок и зачем он им понадобился.", "bg": "oak-conversation.webp"}, {"speaker": "Дуб с цепями", "text": "Нет.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "Что — нет? Они не за ним пришли?", "bg": "oak-conversation.webp"}, {"speaker": "Дуб с цепями", "text": "Лес думает, что защищает себя.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "От ребёнка? Ты слышишь, что говоришь? Что он мог сделать лесу?", "bg": "oak-conversation.webp"}, {"speaker": "Дуб с цепями", "text": "Не то, что сделал. То, что может вырасти из него. Лес боится зла, которого ещё нет.", "bg": "oak-conversation.webp", "oakFact": "forest-fear"}, {"speaker": "Голос", "text": "Вот теперь стало хуже. Они уверены, что спасаются. С такими словами на совести много чего можно не заметить.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "Но это же не значит, что они правы. Нельзя убить ребёнка только потому, что кто-то испугался его будущего.", "bg": "oak-conversation.webp"}, {"speaker": "Дуб с цепями", "text": "Я сказал, что думает лес. Не сказал, что будет.", "bg": "oak-conversation.webp"}, {"speaker": "Влад", "text": "Ладно. Я понял. Они не просто ломятся к нам от злости. Им нужен кто-то маленький, и они считают его угрозой. Но пока я не узнаю правду, никого им не отдам.", "bg": "oak-conversation.webp"}, {"speaker": "Рассказчик", "text": "Корни тихо потрескивают. Влад снова смотрит к лесной кромке. Он знает, кого видел там во время нападений: Леший не пришёл сюда случайно. А кто этот ребёнок — и почему лес боится его — Дуб пока не объяснил.", "bg": "oak-conversation.webp"}], "note": "После второй ночи Дуб сказал: лесным существам нужна не деревня, а конкретный ребёнок. Они считают его источником будущего зла и верят, что защищают лес. Это убеждение леса, а не подтверждённая судьба ребёнка. Кто он, где находится и почему его боятся — пока неизвестно. Влад решил не отдавать никого, пока не выяснит правду."};
const WAVE_DIALOGUES={
 1:[{speaker:'Тьма',bg:'story-shadow.webp',text:'Первая волна отступила. Лес ещё не затих.'},{speaker:'Влад',bg:'story-vlad-return.webp',text:'Я здесь. До деревни я их не пущу.'}],
 2:[{speaker:'Тьма',bg:'story-shadow.webp',text:'Этой ночью их пришло больше. Следующая будет тяжелее.'},{speaker:'Влад',bg:'story-vlad-return.webp',text:'Значит, нужно подготовиться. Я ещё держусь.'}],
 3:[{speaker:'Тьма',bg:'story-shadow.webp',text:'Третья волна отступила. Тот, кто привёл остальных, тоже повержен.'},{speaker:'Леший',bg:'scout-forest.webp',text:'Ты отбился, Влад. Теперь послушай меня.'},{speaker:'Влад',bg:'story-vlad-return.webp',text:'Говори. Я слушаю.'}]
};
function migrateDefense(){const d=DefenseRules.ensure(game);if(game.ui.sceneTime==='day')game.ui.sceneTime='evening';if(game.phase==='event'){game.phase='day';game.ui.openModal=null}if(d.stage==='active')game.phase='combat';if(d.stage==='dialogue')game.phase='waveDialogue';if(d.stage==='defeat')game.phase='defeat';}
function defenseActive(){return game.phase==='combat'&&game.defense?.stage==='active'}
function defenseNovelActive(){return game.defense?.stage==='dialogue'}
function defenseLines(){return WAVE_DIALOGUES[game.defense.wave]||WAVE_DIALOGUES[1]}
let defenseNotice=null,defenseNoticeTimer=0;
function showDefenseResult(){clearTimeout(defenseNoticeTimer);const notice={owner:game,wave:game.defense.completed,expires:Date.now()+18000};defenseNotice=notice;defenseNoticeTimer=setTimeout(()=>{if(defenseNotice!==notice)return;defenseNotice=null;const panel=document.querySelector('.defense-status');if(panel){panel.classList.add('leaving');setTimeout(()=>panel.remove(),400)}},18000)}
function defenseStatus(){const notice=defenseNotice;if(!notice||notice.owner!==game||Date.now()>=notice.expires||game.phase!=='day')return '';return `<section class="defense-status panel" role="status" aria-label="Итог защиты деревни"><div class="defense-heading">${brand(106)}<strong>Волна ${notice.wave} / 3 отражена</strong><span>${notice.wave===3?'Деревня защищена':'Победа'}</span></div><p>${notice.wave===3?'Три волны отражены. Можно исследовать деревню.':'До следующей ночи можно пополнить запасы и подготовить деревню.'}</p></section>`}

function equipmentTray(){const herbs=game.hero.bag.filter(i=>i.use==='heal').reduce((sum,i)=>sum+i.qty,0);return `<div class="bottom-tray defense-tray ${game.ui.bottomPanelOpen?'':'collapsed'}"><div class="tray-head"><div class="tray-tabs"><strong>Снаряжение</strong></div><button class="text-button tray-toggle" data-action="trayToggle" aria-expanded="${game.ui.bottomPanelOpen}"><span>${game.ui.bottomPanelOpen?'Свернуть':'Развернуть'}</span>${brand(86)}</button></div><div class="tray-content" ${game.ui.bottomPanelOpen?'':'inert'}><div class="cards equipment-cards"><button class="card" data-action="defenseAttack"><span class="equipment-icon">${icon(36)}</span><span class="card-copy"><strong>${esc(game.hero.equipment.weapon)}</strong><small>Удар по ближайшему врагу · Пробел</small></span></button><button class="card" data-action="defenseHeal" ${!herbs||game.hero.hp>=game.hero.hpMax?'disabled':''}><span class="equipment-icon">${icon(56)}</span><span class="card-copy"><strong>Плакун-трава · ${herbs}</strong><small>Восстановить 2 сердца · H</small></span></button><button class="card" data-action="defenseFlash" ${game.resources.candles<1||game.defense.lightCooldown>0||!game.hero.bag.some(i=>i.itemId==='Фонарь'&&i.qty>0)?'disabled':''}><span class="equipment-icon">${icon(56)}</span><span class="card-copy"><strong>Фонарь</strong><small>Остановить врагов рядом на 3 с · 1 свеча · F</small></span></button><div class="card passive-equipment"><span class="equipment-icon">${icon(37)}</span><span class="card-copy"><strong>${esc(game.hero.equipment.shield)}</strong><small>Защит от удара: ${game.defense.shield}</small></span></div></div></div></div>`}
function defenseChanged(){if(game.screen==='game')render();else saveLocal()}
function defenseVictory(){if(game.defense.stage!=='dialogue')return;game.ui.novelIndex=0;game.ui.textShown=0;game.ui.novelAuto=false;game.ui.novelHistory=[];game.ui.openModal=null;lastNovelBg='';go('novel')}
function defenseDefeat(){modal('defenseDefeat')}
let defenseStarting=false;
async function beginDefense(){if(window.VillageProgress&&!window.VillageProgress.readiness(game).ready){modal('restoration');return;}if(defenseStarting||game.phase!=='day'||game.screen!=='game'||game.defense.completed>=3||modalClosing||screenTransition)return;defenseStarting=true;const snapshot=game;game.ui.openModal=null;game.ui.placing=null;game.ui.sceneTime='night';render();try{const preparation=window.village3D.prepareDefense(game.defense.completed+1);const intro=window.nightIntro.play(game.defense.completed+1,preparation);const [enemies,finished]=await Promise.allSettled([preparation,intro]);if(game!==snapshot||game.phase!=='day'||game.screen!=='game')return;if(enemies.status==='rejected')throw enemies.reason;if(finished.status==='rejected')console.error('Night intro failed; continuing prepared wave',finished.reason);if(!DefenseRules.begin(game,enemies.value))return;discoverCreature('leshy','wave-'+game.defense.wave);game.ui.bottomPanelOpen=true;render();notify('Нападение началось. Выбери врага, чтобы атаковать.','major')}catch(error){if(game===snapshot&&game.phase==='day'&&game.screen==='game'){game.ui.sceneTime='evening';render();notify(error.message,'error')}}finally{defenseStarting=false}}

function finishDefenseDialogue(){if(!DefenseRules.settle(game))return;const d=game.defense,lines=[];const food=Math.max(1,4+2*game.buildings.hut-2*game.buildings.oven-(game.hero.learnedSkills.includes('bless')?4:0));if(game.resources.grain<food){game.fear=Math.min(100,game.fear+10);lines.push('Не хватило зерна: страх +10')}const spent=Math.min(food,game.resources.grain);game.resources.grain-=spent;lines.push('Зерно −'+spent+' · еда для жителей');const p=production();for(const key of ['wood','stone','grain'])if(p[key]){game.resources[key]+=p[key];lines.push(RES[key][0]+' +'+p[key]+' · работа жителей')}const silver=10+2*Math.max(0,game.hero.stats.luck-2);game.resources.silver+=silver;lines.push('Серебро +'+silver);let protection=5*game.buildings.tower+3*game.buildings.totem+2*game.buildings.well+p.guard+(game.hero.learnedSkills.includes('ward')?4+2*Math.max(0,game.hero.stats.faith-2):0)+(game.hero.learnedSkills.includes('cry')?5:0);if(game.buildings.circle&&game.resources.candles){const rites=Math.min(game.buildings.circle,game.resources.candles);game.resources.candles-=rites;protection+=4*rites;lines.push('Свечи −'+rites+' · обрядные круги')}game.fear=Math.max(0,Math.min(100,game.fear-protection+({'Лучина':-4,'Сказ':0,'Былина':7}[game.settings.difficulty]||0)));if(protection)lines.push('Защита деревни: страх −'+protection);if(game.buildings.oven&&game.hero.hp<game.hero.hpMax)game.hero.hp++;const xp=25+10*d.wave;gainXp(xp,true);lines.push('Опыт +'+xp);game.story.waveReports??=[];if(!game.story.waveReports.some(n=>n.wave===d.wave))game.story.waveReports.push({id:'wave-report-'+d.wave,wave:d.wave,title:'Ночь '+d.wave+' · деревня устояла',image:d.wave===3?'scout-forest.webp':'story-shadow.webp',lead:defenseLines().map(l=>l.speaker+': '+l.text).join(' ')+(d.enemies.some(e=>e.kind==='leshy')?(d.wave<3?' Леший руководил нападением у лесной кромки, затем ушёл в лес.':' Леший вступил в бой после остальных и был побеждён.') : ''),prototype:true});game.journal.push('Отбита волна '+d.wave+' из 3. Влад защитил деревню от нападения из леса.');game.ui.outcome={title:'Волна '+d.wave+' отражена',text:d.completed===3?'Три ночных нападения позади. Можно вернуться к деревне.':'До следующей ночи есть время подготовиться.',lines};game.ui.novelIndex=0;game.ui.textShown=0;lastNovelBg='';go('game')}
function defenseReturn(){const d=game.defense;if(d.stage!=='outcome')return false;game.phase='day';d.stage=d.completed>=3?'complete':'preparation';d.enemies=[];d.checkpoint=null;game.day++;recordStoryEvent('wave-'+d.completed,d.completed===3?'scout-forest.webp':'story-shadow.webp','Ночь '+d.completed+' отражена');game.ui.sceneTime='evening';game.ui.openModal=null;game.ui.outcome=null;game.ui.bottomPanelOpen=false;showDefenseResult();commitGo('game');notify(d.completed===3?'Все три волны отражены':'Вечер подготовки · следующая волна '+(d.completed+1),'major');return true}
function defenseModal(m){if(m.type==='defenseDefeat')return {title:'Влад не удержал нападение',body:'<p>Можно повторить эту волну с запасами и жизнями, которые были перед её началом, или загрузить сохранение.</p><div class="row"><button class="button" data-action="defenseRetry">Повторить волну</button><button class="ghost" data-action="saves">Сохранения</button><button class="ghost" data-action="menu">Главное меню</button></div>'};if(m.type==='domovoyTrade')return {title:'Домовой · припасы и обмен',body:domovoyShop(m.tab||'buy')};return null}
function openDomovoy(){if(game.screen!=='game'||game.phase!=='day'||!window.village3D.canTradeDomovoy())return;discoverCreature('domovoy','trade');modal('domovoyTrade',{tab:'buy'})}
function domovoyShop(tab){if(window.VillageProgress&&!VillageProgress.repairCount(game,'market_ruin')&&!VillageProgress.repairCount(game,'tent_ruin'))return '<p>— Сперва крышу да прилавок мне верни. Три мотка верёвки ещё в деревенских запасах; дальше будем меняться.</p><div class="row"><button class="button" data-action="restoration">Найти торговое место</button><button class="ghost" data-action="domovoyTalk">Поговорить</button></div>';const rows=tab==='exchange'?DefenseRules.EXCHANGES:DefenseRules.SHOP;return `<div class="trade-wallet">${resourceHud()}</div><nav class="trade-tabs"><button class="ghost ${tab==='buy'?'active':''}" data-action="tradeTab" data-id="buy" aria-pressed="${tab==='buy'}">Покупка</button><button class="ghost ${tab==='exchange'?'active':''}" data-action="tradeTab" data-id="exchange" aria-pressed="${tab==='exchange'}">Обмен</button></nav><div class="trade-grid">${rows.map(row=>{const owned=row.upgrade&&game.domovoy.upgrades[row.upgrade],ok=canAfford(row.cost)&&!owned;return `<article class="trade-card panel"><div class="trade-item-title">${icon(row.icon||43)}<h3 class="subhead">${esc(row.name)}</h3></div><p>${esc(row.description||'Получишь: '+(row.item?'лечебный корень · 1':costText(row.gain)))}</p><div class="trade-price">${cardResourceCost(row.cost)}</div><button class="button" data-action="tradeConfirm" data-id="${row.id}" ${ok?'':'disabled'}>${owned?'Приобретено':!ok?'Не хватает ресурсов':tab==='exchange'?'Обменять':'Купить'}</button></article>`}).join('')}</div><section class="domovoy-gifts"><h3 class="subhead">Подарок Домовому</h3><p>Благосклонность: ${game.domovoy.favour} / 100</p><div class="row"><button class="ghost" data-action="gift" data-id="porridge" ${game.resources.grain<3||game.domovoy.favour>=100?'disabled':''}>Каша ${cardResourceCost({grain:3})}<small>+15 благосклонности</small></button><button class="ghost" data-action="gift" data-id="ribbon" ${game.resources.cloth<1||game.domovoy.favour>=100?'disabled':''}>Красная лента ${cardResourceCost({cloth:1})}<small>+30 благосклонности</small></button></div></section><p class="trade-help">Обмен выполняется сразу. Цена показана у каждого предложения.</p>`}
function handleDefenseAction(action,id){if(['defenseAttack','defenseHeal','defenseFlash'].includes(action)&&(game.screen!=='game'||game.ui.openModal||game.defense.stage!=='active'))return true;if(action==='defenseFlash'){if(DefenseRules.flash(game)){render();notify('Свет задержал ближайших врагов на 3 секунды')}else notify('Фонарь не готов, нет свечи или рядом нет врагов','error');return true}if(action==='defenseBegin'){beginDefense();return true}if(action==='defenseAttack'){window.village3D?.attack();return true}if(action==='defenseHeal'){if(DefenseRules.heal(game)){render();notify('Восстановлено до 2 сердец')}else notify('Лечение сейчас недоступно','error');return true}if(action==='defenseRetry'){if(DefenseRules.retry(game)){game.ui.openModal=null;window.village3D?.syncWarrior();game.ui.bottomPanelOpen=true;render()}return true}if(action==='domovoyTrade'){openDomovoy();return true}if(action==='tradeTab'&&game.ui.openModal?.type==='domovoyTrade'){game.ui.openModal.tab=id==='exchange'?'exchange':'buy';render();return true}if(action==='tradeConfirm'&&game.ui.openModal?.type==='domovoyTrade'){if(!window.village3D.canTradeDomovoy())return true;const result=DefenseRules.trade(game,id,game.ui.openModal.tab);if(result.ok){game.journal.push('День '+game.day+' · Домовой: '+result.row.name+'. Расход: '+costText(result.row.cost)+'.');window.storyAudio?.action('buy');render();notify(result.row.name+' · получено')}else notify(result.reason,'error');return true}return false}
function readyWaveTopics(source){const records=source==='oak'?game.story.waveTopics:game.story.residentRequests,registry=source==='oak'?window.WAVE_CONTENT.oak:window.WAVE_CONTENT.residents;return records.filter(t=>!t.read&&game.defense.completed>=t.wave&&(source==='oak'||game.villagers.some(v=>v.id===t.speaker))&&Array.isArray(registry[t.wave]?.lines)&&registry[t.wave].lines.length).map(t=>{t.status='available';return t})}
function waveConversationLines(){const talk=game.ui.waveTalk;if(!talk)return null;return (talk.source==='oak'?window.WAVE_CONTENT.oak:window.WAVE_CONTENT.residents)[talk.wave]?.lines||[]}
function beginWaveConversation(source,id){if(game.phase!=='day')return;const record=readyWaveTopics(source).find(t=>t.id===id);if(!record)return;game.ui.waveTalk={...record,source};game.ui.waveTalkCheckpoint=game.ui.oakActive&&game.ui.oakCheckpoint?{...game.ui.oakCheckpoint}:{novelIndex:game.ui.novelIndex,novelChoice:game.ui.novelChoice,novelHistory:game.ui.novelHistory,textShown:game.ui.textShown,novelAuto:game.ui.novelAuto};delete game.ui.oakCheckpoint;delete game.ui.oakMode;game.ui.oakActive=false;game.ui.novelIndex=Math.min(record.nextLine||0,(source==='oak'?window.WAVE_CONTENT.oak:window.WAVE_CONTENT.residents)[record.wave].lines.length-1);game.ui.textShown=0;game.ui.novelAuto=false;lastNovelBg='';if(game.screen==='novel')commitGo('novel');else go('novel')}
function finishWaveConversation(){const talk=game.ui.waveTalk;if(!talk)return;const records=talk.source==='oak'?game.story.waveTopics:game.story.residentRequests,record=records.find(t=>t.id===talk.id),entry=(talk.source==='oak'?window.WAVE_CONTENT.oak:window.WAVE_CONTENT.residents)[talk.wave];if(record&&!record.read){record.read=true;record.status='read';recordStoryEvent(talk.id,entry.lines.at(-1)?.bg||'oak-conversation.webp',entry.title||'Разговор после ночи '+talk.wave);const title=entry.title||'После волны '+talk.wave,text=entry.note||entry.lines.map(l=>l.text).join(' '),speaker=talk.source==='oak'?'Дуб с цепями':game.villagers.find(v=>v.id===talk.speaker)?.name||'Житель';game.dialogueNotes.push({id:talk.id,villagerId:talk.source==='oak'?'ancient_oak':talk.speaker,speaker,title,text,place:'Выселки',day:game.day});game.journal.push(speaker+': '+title+'. '+text)}game.ui.waveTalk=null;if(game.ui.waveTalkCheckpoint)Object.assign(game.ui,game.ui.waveTalkCheckpoint);delete game.ui.waveTalkCheckpoint;go('game');notify('Разговор записан в дневнике')}
function pendingResidentButton(id){const t=readyWaveTopics('resident').find(t=>t.speaker===id);return t?`<button class="button resident-request" data-action="residentWaveTalk" data-id="${t.id}">${brand(88)} Хочет поговорить</button>`:''}

function cancelWaveConversation(){const talk=game.ui.waveTalk;if(talk){const record=(talk.source==='oak'?game.story.waveTopics:game.story.residentRequests).find(t=>t.id===talk.id);if(record)record.nextLine=game.ui.novelIndex}game.ui.waveTalk=null;if(game.ui.waveTalkCheckpoint)Object.assign(game.ui,game.ui.waveTalkCheckpoint);delete game.ui.waveTalkCheckpoint;go('game')}
